// Tiny synthetic replay cache generated by the same Parquet writer family as the shipped parser.

use parquet::{
    basic::Compression,
    data_type::{BoolType, ByteArray, ByteArrayType, DataType, FloatType, Int32Type, Int64Type},
    file::{
        properties::WriterProperties,
        writer::{SerializedFileWriter, SerializedRowGroupWriter},
    },
    schema::parser::parse_message_type,
};
use serde_json::{json, Value};
use sha2::{Digest, Sha256};
use std::{
    fs::{self, File, FileTimes},
    io::Write,
    path::{Path, PathBuf},
    sync::Arc,
    time::{Duration, UNIX_EPOCH},
};

pub(super) const CURRENT: &str = "cache/demo-replay/matches";
pub(super) const LEGACY: &str = "replay-match";
pub(super) const TICKS: [i32; 6] = [100, 102, 104, 104, 109, 111];
const MODIFIED_NS: u64 = 1_735_689_600_000_000_100;
const DEMO_BYTES: &[u8] = b"fixture only; no CS2 demo content";
const SCHEMA: &str = "
message fixture {
    REQUIRED INT32 tick;
    REQUIRED INT64 steamid (UINT_64);
    OPTIONAL BINARY name (UTF8);
    REQUIRED INT32 team_num;
    REQUIRED FLOAT X;
    REQUIRED FLOAT Y;
    REQUIRED FLOAT Z;
    REQUIRED FLOAT yaw;
    REQUIRED BOOLEAN is_alive;
    REQUIRED BOOLEAN has_helmet;
    REQUIRED BOOLEAN has_defuser;
    REQUIRED BOOLEAN has_c4;
    REQUIRED INT32 health;
    REQUIRED INT32 armor;
    REQUIRED INT32 balance;
    REQUIRED INT32 current_equip_value;
    REQUIRED BINARY inventory (UTF8);
    REQUIRED BINARY active_weapon (UTF8);
    REQUIRED BINARY active_weapon_name (UTF8);
    REQUIRED FLOAT flash_duration;
    REQUIRED INT32 player_color;
}";

pub(super) struct ReplayFixture {
    pub demo: PathBuf,
    pub key: String,
    pub metadata: Value,
}

impl ReplayFixture {
    pub(super) fn new(profile: &Path) -> Self {
        let upload = profile.join("fixture-temp/cs2_insight_demos");
        fs::create_dir_all(&upload).unwrap();
        let demo = upload.join("Fixture 回放.dem");
        let mut file = File::create(&demo).unwrap();
        file.write_all(DEMO_BYTES).unwrap();
        file.set_times(
            FileTimes::new().set_modified(UNIX_EPOCH + Duration::from_nanos(MODIFIED_NS)),
        )
        .unwrap();
        drop(file);

        let path = fs::canonicalize(&demo).unwrap();
        let path = path.to_str().unwrap();
        let path = path.strip_prefix(r"\\?\").unwrap_or(path);
        let key = format!(
            "{:x}",
            Sha256::digest(format!(
                "5|0.41.4+cs2insight7|{path}|{}|{MODIFIED_NS}|32.000000|64.000000",
                DEMO_BYTES.len()
            ))
        )[..40]
            .to_owned();
        let metadata = json!({
            "version": 5, "cache_key": key, "tick_rate": 64.0, "fps": 32.0,
            "demo_fingerprint": {"path": path, "size": DEMO_BYTES.len(), "mtime_ns": MODIFIED_NS},
            "pov_player_name": "玩家 Alpha", "pov_steamid64": "76561198000000123",
            "map_transform": {"scale": 4.125, "pos_x": -1290, "pos_y": 2400},
            "effect_tracks_version": 3, "effect_capabilities": {"smoke": true},
            "effect_warnings": ["fixture warning"],
            "effect_tracks": [
                {"kind":"old","start_tick":10,"end_tick":99},
                {"kind":"smoke","start_tick":98,"end_tick":100,"payload":{"name":"烟"}},
                {"kind":"fire","start_tick":112,"end_tick":118},
                {"kind":"future","start_tick":113,"end_tick":120},
                "ignored"
            ],
            "rounds": [
                {"round_number": 1, "start_tick": 10, "end_tick": 90, "row_group": 0, "sample_ticks":[10]},
                {"round_number": 2, "start_tick": 100, "end_tick": 112, "row_group": 1, "sample_ticks": TICKS,
                 "shots": [{"tick":102,"player":"玩家"},"ignored"],
                 "events": [{"type":"kill","tick":109},null]}
            ]
        });
        Self {
            demo,
            key,
            metadata,
        }
    }

    pub(super) fn write(&self, profile: &Path, directory: &str) -> (PathBuf, PathBuf) {
        let root = profile.join(directory);
        fs::create_dir_all(&root).unwrap();
        let parquet = root.join(format!("{}.parquet", self.key));
        let meta = root.join(format!("{}.meta.json", self.key));
        write_parquet(&parquet);
        fs::write(&meta, serde_json::to_vec(&self.metadata).unwrap()).unwrap();
        (parquet, meta)
    }

    pub(super) fn request(&self) -> Value {
        json!({"path": self.demo, "start_tick":100, "end_tick":112})
    }
}

fn write_parquet(path: &Path) {
    let schema = Arc::new(parse_message_type(SCHEMA).unwrap());
    let properties = Arc::new(
        WriterProperties::builder()
            .set_compression(Compression::ZSTD(Default::default()))
            .build(),
    );
    let mut writer =
        SerializedFileWriter::new(File::create(path).unwrap(), schema, properties).unwrap();
    for ticks in [&[10, 15][..], &[100, 100, 102, 104, 107, 109][..]] {
        let mut row_group = writer.next_row_group().unwrap();
        let len = ticks.len();
        column::<Int32Type>(&mut row_group, ticks, None);
        column::<Int64Type>(
            &mut row_group,
            &[
                76561198000000123,
                11,
                76561198000000456,
                76561198000000123,
                41,
                76561198000000456,
            ][..len],
            None,
        );
        let names = [
            "玩家 Alpha",
            "Bench",
            "Bravo",
            "玩家 Alpha",
            "Not sampled",
            "Bravo",
        ]
        .map(ByteArray::from);
        column::<ByteArrayType>(&mut row_group, &names[..len], Some(&[1; 6][..len]));
        column::<Int32Type>(&mut row_group, &[2, 1, 3, 2, 2, 3][..len], None);
        for values in [
            [-123.25, 4.0, 88.5, -7.0, 0.0, 166.25],
            [99.25, 0.0, 2.0, 8.0, -1.0, -158.5],
            [32.0, 16.0, 8.0, 4.0, 2.0, 1.0],
            [170.0, 0.0, -90.0, -180.0, 10.0, 3.25],
        ] {
            column::<FloatType>(&mut row_group, &values[..len], None);
        }
        for values in [
            [true, false, true, false, true, true],
            [true, false, false, true, false, true],
            [false, false, true, false, false, true],
            [true, false, false, false, false, true],
        ] {
            column::<BoolType>(&mut row_group, &values[..len], None);
        }
        for values in [
            [100, 65, 25, -1, 77, 38],
            [95, 0, 80, 0, 0, 70000],
            [1200, 0, 120, 0, 0, 3300],
            [4400, 0, 2875, 600, 0, 8721],
        ] {
            column::<Int32Type>(&mut row_group, &values[..len], None);
        }
        for values in [
            [
                "[\"ak47\",\"smoke\"]",
                "[]",
                "[\"m4a1\"]",
                "[]",
                "[]",
                "[\"awp\"]",
            ],
            ["ak47", "", "m4a1", "knife", "aug", "awp"],
            ["AK-47", "", "M4A1", "Knife", "AUG", "AWP"],
        ] {
            column::<ByteArrayType>(
                &mut row_group,
                &values[..len]
                    .iter()
                    .copied()
                    .map(ByteArray::from)
                    .collect::<Vec<_>>(),
                None,
            );
        }
        column::<FloatType>(
            &mut row_group,
            &[1.25, 0.0, -5.0, 0.0, 2.0, 3.5][..len],
            None,
        );
        column::<Int32Type>(&mut row_group, &[1, 0, 2, 1, 0, 2][..len], None);
        assert!(row_group.next_column().unwrap().is_none());
        row_group.close().unwrap();
    }
    writer.close().unwrap();
}

fn column<T: DataType>(
    group: &mut SerializedRowGroupWriter<'_, File>,
    values: &[T::T],
    definition: Option<&[i16]>,
) {
    let mut column = group.next_column().unwrap().unwrap();
    assert_eq!(
        column
            .typed::<T>()
            .write_batch(values, definition, None)
            .unwrap(),
        values.len()
    );
    column.close().unwrap();
}
